function cleanText(value) {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  if (!text || ['null', 'undefined'].includes(text.toLowerCase())) return null;
  return text;
}
const input = $json || {};
const conversionOutboxId = cleanText(input.conversion_outbox_id || input.outbox_id || input.id);
const dispatchMode = cleanText(input.dispatch_mode) || 'inline';
const claimedAttempt = input.claimed_attempt === undefined || input.claimed_attempt === null
  ? null : Number(input.claimed_attempt);
if (!['inline', 'scheduled'].includes(dispatchMode)) throw new Error('invalid_dispatch_mode');
if (dispatchMode === 'scheduled' && (!conversionOutboxId || !Number.isInteger(claimedAttempt))) {
  throw new Error('scheduled_claim_context_required');
}
return [{ json: { conversion_outbox_id: conversionOutboxId, dispatch_mode: dispatchMode,
  claimed_attempt: claimedAttempt, received_input: input } }];

/**
 * 03 - Build Meta Request v3 Credential
 *
 * Este node NÃO envia para a Meta.
 * Ele valida a linha da conversion_outbox, monta o payload e entrega para o node HTTP Request.
 * O token agora deve vir de uma credencial do n8n no node HTTP:
 * - Credential type: Query Auth
 * - Name: access_token
 * - Value: token da Meta
 */

const DEFAULT_GRAPH_VERSION = 'v23.0';

function pick(...values) {
  return values.find(value => value !== undefined && value !== null && value !== '') || null;
}

function cleanText(value) {
  if (value === undefined || value === null) return null;

  const text = String(value).trim();

  const invalidValues = [
    '',
    'null',
    'undefined',
    'nao identificado',
    'não identificado',
    'nao_identificado',
    'não_identificado',
    'n/a',
    'sem informação',
    'sem informacao'
  ];

  if (invalidValues.includes(text.toLowerCase())) return null;

  return text;
}

function normalizeKey(value) {
  const text = cleanText(value);
  if (!text) return null;

  return text
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .replace(/\s+/g, '_')
    .replace(/-/g, '_')
    .toLowerCase();
}

function parseBoolean(value, defaultValue = null) {
  if (value === undefined || value === null || value === '') return defaultValue;
  if (typeof value === 'boolean') return value;

  const text = normalizeKey(value);

  if (['true', '1', 'yes', 'sim', 'ativo', 'enabled'].includes(text)) return true;
  if (['false', '0', 'no', 'nao', 'não', 'inativo', 'disabled'].includes(text)) return false;

  return defaultValue;
}

function normalizePhone(value) {
  const text = cleanText(value);
  if (!text) return null;
  const digits = text.replace(/\D/g, '');
  return digits || null;
}

function normalizeForHash(value, type = 'text') {
  const text = cleanText(value);
  if (!text) return null;

  if (type === 'email') return text.toLowerCase();
  if (type === 'phone') return normalizePhone(text);
  if (type === 'name') {
    return text
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase()
      .trim();
  }

  return text.toLowerCase().trim();
}

async function sha256(value) {
  const text = cleanText(value);
  if (!text) return null;

  function rightRotate(value, amount) {
    return (value >>> amount) | (value << (32 - amount));
  }

  const mathPow = Math.pow;
  const maxWord = mathPow(2, 32);
  const lengthProperty = 'length';

  let i;
  let j;

  const result = '';
  const words = [];
  const asciiBitLength = text[lengthProperty] * 8;

  let hash = sha256.h = sha256.h || [];
  let k = sha256.k = sha256.k || [];
  let primeCounter = k[lengthProperty];

  const isComposite = {};

  for (let candidate = 2; primeCounter < 64; candidate++) {
    if (!isComposite[candidate]) {
      for (i = 0; i < 313; i += candidate) {
        isComposite[i] = candidate;
      }

      hash[primeCounter] = (mathPow(candidate, 0.5) * maxWord) | 0;
      k[primeCounter++] = (mathPow(candidate, 1 / 3) * maxWord) | 0;
    }
  }

  let message = unescape(encodeURIComponent(text));

  message += '\x80';

  while (message[lengthProperty] % 64 - 56) {
    message += '\x00';
  }

  for (i = 0; i < message[lengthProperty]; i++) {
    j = message.charCodeAt(i);

    if (j >> 8) {
      throw new Error('sha256_invalid_character');
    }

    words[i >> 2] |= j << (((3 - i) % 4) * 8);
  }

  words[words[lengthProperty]] = ((asciiBitLength / maxWord) | 0);
  words[words[lengthProperty]] = asciiBitLength;

  for (j = 0; j < words[lengthProperty];) {
    const w = words.slice(j, j += 16);
    const oldHash = hash.slice(0);

    for (i = 0; i < 64; i++) {
      const w15 = w[i - 15];
      const w2 = w[i - 2];

      const a = hash[0];
      const e = hash[4];

      const temp1 = hash[7]
        + (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25))
        + ((e & hash[5]) ^ ((~e) & hash[6]))
        + k[i]
        + (w[i] = (i < 16)
          ? w[i]
          : (
            w[i - 16]
            + (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3))
            + w[i - 7]
            + (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))
          ) | 0);

      const temp2 = (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22))
        + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));

      hash = [
        (temp1 + temp2) | 0,
        hash[0],
        hash[1],
        hash[2],
        (hash[3] + temp1) | 0,
        hash[4],
        hash[5],
        hash[6]
      ];
    }

    for (i = 0; i < 8; i++) {
      hash[i] = (hash[i] + oldHash[i]) | 0;
    }
  }

  let hex = '';

  for (i = 0; i < 8; i++) {
    for (j = 3; j + 1; j--) {
      const byte = (hash[i] >> (j * 8)) & 255;
      hex += ((byte < 16) ? '0' : '') + byte.toString(16);
    }
  }

  return hex;
}

async function hashUserValue(value, type = 'text') {
  const normalized = normalizeForHash(value, type);
  if (!normalized) return null;
  return await sha256(normalized);
}

function unixTimeFrom(value) {
  const text = cleanText(value);
  const date = text ? new Date(text) : new Date();

  if (Number.isNaN(date.getTime())) {
    return Math.floor(Date.now() / 1000);
  }

  return Math.floor(date.getTime() / 1000);
}

function parseMoney(value) {
  const cleaned = cleanText(value);
  if (!cleaned) return null;
  if (typeof value === 'number') return value;

  const text = String(cleaned)
    .replace(/[R$\s]/g, '')
    .replace(/\./g, '')
    .replace(',', '.');

  const number = Number(text);
  if (Number.isNaN(number)) return null;
  return number;
}

function isValidCtwaClid(value) {
  const text = cleanText(value);
  if (!text) return false;
  return text.length >= 20;
}

function makeResult(row, finalStatus, lastError, metaResponse = null) {
  return {
    json: {
      should_send_to_meta: false,
      outbox_id: row?.outbox_id,
      normalized_event_id: row?.normalized_event_id,
      event_code: row?.event_code,
      route: row?.route,
      meta_event_name: row?.meta_event_name,
      final_status: finalStatus,
      last_error: lastError,
      meta_response: metaResponse || {
        error: lastError,
        route: row?.route,
        meta_event_name: row?.meta_event_name
      }
    }
  };
}

function extractLeadOrigemBucket(row) {
  return cleanText(
    pick(
      row.outbox_payload?.lead_origem_bucket,
      row.outbox_payload?.routing_checks?.lead_origem_bucket
    )
  );
}

function extractLeadEntradaBucket(row) {
  return cleanText(
    pick(
      row.outbox_payload?.lead_entrada_bucket,
      row.outbox_payload?.routing_checks?.lead_entrada_bucket
    )
  );
}

async function buildStandardEvent(row, clientConfig, eventTime, eventId, currency) {
  const userData = {};

  const emailHash = await hashUserValue(
    pick(row.outbox_payload?.user_data_source?.email, row.email),
    'email'
  );

  const phoneHash = await hashUserValue(
    pick(row.outbox_payload?.user_data_source?.phone, row.phone, row.phone_raw),
    'phone'
  );

  const firstNameHash = await hashUserValue(
    pick(row.outbox_payload?.user_data_source?.first_name, row.first_name),
    'name'
  );

  const lastNameHash = await hashUserValue(
    pick(row.outbox_payload?.user_data_source?.last_name, row.last_name),
    'name'
  );

  const externalIdHash = await hashUserValue(
    pick(row.outbox_payload?.user_data_source?.contact_id, row.contact_id),
    'text'
  );

  if (emailHash) userData.em = [emailHash];
  if (phoneHash) userData.ph = [phoneHash];
  if (firstNameHash) userData.fn = [firstNameHash];
  if (lastNameHash) userData.ln = [lastNameHash];
  if (externalIdHash) userData.external_id = [externalIdHash];

  const fbp = cleanText(pick(row.outbox_payload?.attribution?.fbp, row.fbp));
  const fbc = cleanText(pick(row.outbox_payload?.attribution?.fbc, row.fbc));
  const fbclid = cleanText(pick(row.outbox_payload?.attribution?.fbclid, row.fbclid));

  if (fbp) userData.fbp = fbp;
  if (fbc) userData.fbc = fbc;

  // Compatibilidade legado: ainda construímos fbc quando só há fbclid.
  // Para novas jornadas web, preferir sempre o _fbc capturado no browser.
  if (!fbc && fbclid) userData.fbc = `fb.1.${Date.now()}.${fbclid}`;

  const clientIpAddress = cleanText(
    pick(
      row.outbox_payload?.attribution?.client_ip_address,
      row.outbox_payload?.user_data_source?.client_ip_address
    )
  );

  const clientUserAgent = cleanText(
    pick(
      row.outbox_payload?.attribution?.client_user_agent,
      row.outbox_payload?.user_data_source?.client_user_agent
    )
  );

  if (clientIpAddress) userData.client_ip_address = clientIpAddress;
  if (clientUserAgent) userData.client_user_agent = clientUserAgent;

  const value = parseMoney(pick(row.outbox_payload?.custom_data?.value, row.valor_ganho));

  const customData = { currency };

  if (row.meta_event_name === 'Purchase') {
    customData.value = value ?? 0;
  } else if (value !== null) {
    customData.value = value;
  }

  const procedimento = cleanText(
    pick(row.outbox_payload?.custom_data?.procedimento_ganho, row.procedimento_ganho)
  );

  if (procedimento) customData.content_name = procedimento;

  customData.lead_event_source = 'GHL';

  const sourceUrl = cleanText(
    pick(
      row.outbox_payload?.attribution?.source_url,
      row.source_url
    )
  );

  // V2.4: resolve o bucket dentro do próprio escopo da função.
  // Antes, buildStandardEvent() referenciava leadEntradaBucket,
  // mas essa variável só existia localmente dentro de buildOne().
  // Em rotas standard isso gerava ReferenceError e encerrava o node
  // antes de atualizar a outbox/log.
  const leadEntradaBucket = extractLeadEntradaBucket(row);

  const isWebsiteLead = Boolean(
    row.event_code === 'lead' &&
    row.route === 'standard' &&
    (
      leadEntradaBucket === 'form_site' ||
      row.outbox_payload?.attribution?.meta_routing_evidence === 'fbc' ||
      row.outbox_payload?.attribution?.meta_routing_evidence === 'fbclid'
    )
  );

  const event = {
    event_name: row.meta_event_name,
    event_time: eventTime,
    event_id: eventId,
    action_source: isWebsiteLead ? 'website' : 'system_generated',
    user_data: userData,
    custom_data: customData
  };

  if (sourceUrl) event.event_source_url = sourceUrl;

  return event;
}

function buildWhatsappBusinessMessagingEvent(row, clientConfig, eventTime, eventId, currency) {
  const ctwaClid = cleanText(pick(row.outbox_payload?.attribution?.ctwa_clid, row.ctwa_clid));

  const pageId = cleanText(
    pick(
      clientConfig.meta_page_id,
      clientConfig.page_id,
      row.outbox_payload?.attribution?.page_id
    )
  );

  const wabaId = cleanText(
    pick(
      clientConfig.meta_waba_id,
      clientConfig.waba_id,
      clientConfig.whatsapp_business_account_id
    )
  );

  const value = parseMoney(pick(row.outbox_payload?.custom_data?.value, row.valor_ganho));

  const customData = { currency };

  if (row.meta_event_name === 'Purchase') {
    customData.value = value ?? 0;
  } else if (value !== null) {
    customData.value = value;
  }

  const userData = {
    ctwa_clid: ctwaClid,
    page_id: pageId
  };

  if (wabaId) userData.whatsapp_business_account_id = wabaId;

  return {
    event_name: row.meta_event_name,
    event_time: eventTime,
    event_id: eventId,
    action_source: 'business_messaging',
    messaging_channel: 'whatsapp',
    user_data: userData,
    custom_data: customData
  };
}

async function buildOne(row) {
  if (!row?.outbox_id) {
    return makeResult(row || {}, 'failed', 'outbox_not_found_or_not_pending');
  }

  const clientConfig = row.client_config || {};

  const metaEnabled = parseBoolean(
    pick(clientConfig.meta_enabled, clientConfig.enable_meta_tracking),
    true
  );

  const standardEnabled = parseBoolean(
    pick(clientConfig.meta_standard_enabled, clientConfig.enable_meta_tracking),
    true
  );

  const whatsappEnabled = parseBoolean(
    pick(clientConfig.meta_whatsapp_enabled, clientConfig.enable_meta_tracking),
    true
  );

  if (!metaEnabled) {
    return makeResult(row, 'skipped', 'meta_disabled_for_client');
  }

  if (row.route === 'standard' && !standardEnabled) {
    return makeResult(row, 'skipped', 'meta_standard_disabled_for_client');
  }

  if (row.route === 'whatsapp_bm' && !whatsappEnabled) {
    return makeResult(row, 'skipped', 'meta_whatsapp_disabled_for_client');
  }

  const leadOrigemBucket = extractLeadOrigemBucket(row);
  const leadEntradaBucket = extractLeadEntradaBucket(row);

  // V2.1: o Router (1.1) é a camada que decide se o evento pertence à Meta.
  // O dispatcher apenas valida rota, configuração e matching necessários.
  // Isso evita duplicar a regra de atribuição em dois workflows.

  const datasetId = cleanText(
    pick(
      clientConfig.meta_dataset_id,
      clientConfig.meta_pixel_id,
      clientConfig.pixel_id,
      clientConfig.dataset_id
    )
  );

  if (!datasetId) {
    return makeResult(row, 'failed', 'missing_meta_dataset_id_or_pixel_id');
  }

  if (row.route === 'whatsapp_bm') {
    const ownershipStatus = cleanText(row.meta_source_ownership_status);
    const sourceId = cleanText(row.meta_source_id);
    const primaryAccountId = cleanText(row.meta_primary_account_id);
    const matchedAccountId = cleanText(row.meta_matched_account_id);

    const ownershipDetails = {
      error: null,
      route: row.route,
      meta_event_name: row.meta_event_name,
      source_id: sourceId,
      ownership_status: ownershipStatus,
      primary_account_id: primaryAccountId,
      matched_account_id: matchedAccountId,
      policy: 'primary_meta_ad_account_only'
    };

    // Trava de propriedade: eventos WhatsApp BM só são enviados quando
    // o anúncio pertence à conta Meta primária configurada para o cliente.
    // Página e ctwa_clid não provam qual agência gerenciou o anúncio.
    if (ownershipStatus === 'other_account') {
      ownershipDetails.error = 'meta_source_not_owned_by_impuls';
      return makeResult(
        row,
        'skipped',
        'meta_source_not_owned_by_impuls',
        ownershipDetails
      );
    }

    if (ownershipStatus === 'missing_source_id') {
      ownershipDetails.error = 'meta_source_ownership_unverified_missing_source_id';
      return makeResult(
        row,
        'skipped',
        'meta_source_ownership_unverified_missing_source_id',
        ownershipDetails
      );
    }

    if (ownershipStatus === 'source_not_found') {
      ownershipDetails.error = 'meta_source_ownership_unverified_source_not_found';
      ownershipDetails.retry_class = 'ownership_resolution';
      ownershipDetails.retry_policy = 'wait_for_meta_ads_sync';
      ownershipDetails.retryable = true;

      return makeResult(
        row,
        'pending',
        'meta_source_ownership_unverified_source_not_found',
        ownershipDetails
      );
    }

    if (ownershipStatus === 'missing_primary_account') {
      ownershipDetails.error = 'missing_primary_meta_ad_account_id';
      return makeResult(
        row,
        'failed',
        'missing_primary_meta_ad_account_id',
        ownershipDetails
      );
    }

    if (ownershipStatus !== 'owned_primary_account') {
      ownershipDetails.error = 'meta_source_ownership_unverified';
      return makeResult(
        row,
        'skipped',
        'meta_source_ownership_unverified',
        ownershipDetails
      );
    }

    const ctwaClid = cleanText(pick(row.outbox_payload?.attribution?.ctwa_clid, row.ctwa_clid));

    const pageId = cleanText(
      pick(
        clientConfig.meta_page_id,
        clientConfig.page_id,
        row.outbox_payload?.attribution?.page_id
      )
    );

    if (!isValidCtwaClid(ctwaClid)) {
      return makeResult(row, 'skipped', 'missing_ctwa_clid_for_whatsapp_business_messaging');
    }

    if (!pageId) {
      return makeResult(row, 'failed', 'missing_meta_page_id_for_whatsapp_business_messaging');
    }
  }

  const currency = cleanText(
    pick(
      row.outbox_payload?.custom_data?.currency,
      clientConfig.default_currency,
      'BRL'
    )
  );

  const graphVersion = cleanText(
    pick(
      clientConfig.meta_graph_api_version,
      DEFAULT_GRAPH_VERSION
    )
  );

  const eventTime = unixTimeFrom(
    pick(
      row.event_datetime,
      row.received_at,
      row.outbox_created_at
    )
  );

  const eventId = cleanText(
    pick(
      row.outbox_payload?.event_id,
      ['meta', row.route, row.normalized_event_id, row.event_code].filter(Boolean).join(':')
    )
  );

  let event;

  if (row.route === 'whatsapp_bm') {
    event = buildWhatsappBusinessMessagingEvent(row, clientConfig, eventTime, eventId, currency);
  } else {
    event = await buildStandardEvent(row, clientConfig, eventTime, eventId, currency);
  }

  const requestBody = {
    data: [event]
  };

  const testEventCode = cleanText(
    pick(
      clientConfig.test_event_code,
      clientConfig.meta_test_event_code,
      clientConfig.meta_test_code
    )
  );

  if (testEventCode) {
    requestBody.test_event_code = testEventCode;
  }

  return {
    json: {
      should_send_to_meta: true,
      outbox_id: row.outbox_id,
      dispatch_mode: row.dispatch_mode,
      claimed_attempt: row.claimed_attempt,
      normalized_event_id: row.normalized_event_id,
      event_code: row.event_code,
      route: row.route,
      meta_event_name: row.meta_event_name,
      final_status: null,
      last_error: null,
      meta_request: {
        url: `https://graph.facebook.com/${graphVersion}/${datasetId}/events`,
        request_body: requestBody,
        graph_version: graphVersion,
        dataset_id: datasetId
      }
    }
  };
}

const rows = [$('Get Single Meta Outbox').first().json];
const results = [];

for (const row of rows) {
  results.push(await buildOne(row));
}

return results;

/**
 * Finaliza a resposta do HTTP Request da Meta e transforma no formato usado pelo update da outbox.
 * O token NÃO aparece aqui; ele fica na credencial Query Auth do node HTTP.
 */

function cleanText(value) {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  if (!text || ['null', 'undefined'].includes(text.toLowerCase())) return null;
  return text;
}

function pick(...values) {
  return values.find(value => value !== undefined && value !== null && value !== '') || null;
}

function parseMaybeJson(value) {
  if (value === undefined || value === null) return {};
  if (typeof value === 'object') return value;

  try {
    return JSON.parse(String(value));
  } catch (error) {
    return { raw_response: String(value) };
  }
}

const requestItem = $('Build Meta Request').item.json;
const http = $json || {};

if (http.error) {
  return [
    {
      json: {
        outbox_id: requestItem.outbox_id,
      dispatch_mode: requestItem.dispatch_mode,
      claimed_attempt: requestItem.claimed_attempt,
        dispatch_mode: requestItem.dispatch_mode,
        claimed_attempt: requestItem.claimed_attempt,
        normalized_event_id: requestItem.normalized_event_id,
        event_code: requestItem.event_code,
        route: requestItem.route,
        meta_event_name: requestItem.meta_event_name,
        final_status: 'pending',
        last_error: `network_or_http_node_error: ${http.error.message || http.error}`,
        meta_response: {
          error: http.error,
          request_body: requestItem.meta_request?.request_body || null,
          graph_version: requestItem.meta_request?.graph_version || null,
          dataset_id: requestItem.meta_request?.dataset_id || null
        }
      }
    }
  ];
}

const statusCode = Number(
  pick(
    http.statusCode,
    http.status,
    http.response?.statusCode,
    http.response?.status,
    200
  )
);

const responseBody = parseMaybeJson(
  pick(
    http.body,
    http.data,
    http
  )
);

const eventsReceived = Number(responseBody?.events_received || 0);
const hasMetaError = Boolean(responseBody?.error);

if (statusCode >= 200 && statusCode < 300 && eventsReceived >= 1 && !hasMetaError) {
  return [
    {
      json: {
        outbox_id: requestItem.outbox_id,
      dispatch_mode: requestItem.dispatch_mode,
      claimed_attempt: requestItem.claimed_attempt,
        dispatch_mode: requestItem.dispatch_mode,
        claimed_attempt: requestItem.claimed_attempt,
        normalized_event_id: requestItem.normalized_event_id,
        event_code: requestItem.event_code,
        route: requestItem.route,
        meta_event_name: requestItem.meta_event_name,
        final_status: 'sent',
        last_error: null,
        meta_response: {
          http_status: statusCode,
          body: responseBody,
          request_body: requestItem.meta_request?.request_body || null,
          graph_version: requestItem.meta_request?.graph_version || null,
          dataset_id: requestItem.meta_request?.dataset_id || null,
          auth_strategy: 'n8n_http_query_auth_credential'
        }
      }
    }
  ];
}

const metaErrorMessage = cleanText(
  pick(
    responseBody?.error?.message,
    responseBody?.error?.type,
    responseBody?.raw_response,
    `http_${statusCode}`
  )
);

const retryable = statusCode === 429 || statusCode >= 500;

return [
  {
    json: {
      outbox_id: requestItem.outbox_id,
      dispatch_mode: requestItem.dispatch_mode,
      claimed_attempt: requestItem.claimed_attempt,
      normalized_event_id: requestItem.normalized_event_id,
      event_code: requestItem.event_code,
      route: requestItem.route,
      meta_event_name: requestItem.meta_event_name,
      final_status: retryable ? 'pending' : 'failed',
      last_error: `meta_api_error: ${metaErrorMessage}`,
      meta_response: {
        http_status: statusCode,
        body: responseBody,
        request_body: requestItem.meta_request?.request_body || null,
        graph_version: requestItem.meta_request?.graph_version || null,
        dataset_id: requestItem.meta_request?.dataset_id || null,
        auth_strategy: 'n8n_http_query_auth_credential'
